// ============================================================
// draw.s — ARM64 (Apple Silicon), step 4: High Color edition
//
// void draw_frame(uint32_t *fb, int width, int height, int frame);
//
// What changed this step:
//
//  1. 32K PALETTE: the rainbow table is now 32,768 entries —
//     a true 15-bit High Color gradient (the VESA generation
//     that followed mode 13h's 256 colors).
//
//  2. FIXED-POINT DISTANCE: to actually SEE 32K colors, integer
//     pixel distances aren't fine enough (they'd only ever hit
//     ~64 palette slots inside the halo). So distances are now
//     computed in 1/32-pixel units ("5.5 fixed point"). The
//     trick: sqrt(d2 * 1024) == 32 * sqrt(d2), so shifting d2
//     left 10 bits BEFORE the sqrt gives a result already in
//     1/32px units. One lsl, no extra FP work.
//     (Safe while d2 < 2^21, i.e. radii up to ~1448px.)
//
//  3. SELF-SCALING GEOMETRY: base size = min(width,height)/4,
//     pulse amplitude = base/4. Resize the window, shapes fit.
//
//  4. SLOWER: pulse period is now frame & 1023 (~17s @60fps,
//     was ~4s), and the color flow drifts gently.
//
// Register map:
//   entry:  w9/w10/w11/w12 scratch
//   persistent: w14 = S (int px)     w15 = R32 (R in 1/32px)
//               w16 = phase          x17 = palette base
//   loop:   w3=y w4=x w5=cx w6=cy w7=dx w8=dy w9=|dx| w10=|dy|
//           w11=color  w12=dc32  w13=ds (int px)
//   NOTE: x18 is reserved by Apple — never touch it.
// ============================================================

.global _draw_frame
.p2align 2

_draw_frame:
    // ---- slow triangle oscillator: period 1024 frames ----
    and     w9, w3, #1023       // t = frame & 1023
    mov     w10, #512
    sub     w9, w10, w9
    cmp     w9, #0
    cneg    w9, w9, lt          // |512 - t|   0..512
    sub     w9, w9, #256        // tri  (-256..+256)

    // ---- geometry scales with the window ----
    cmp     w1, w2
    csel    w10, w1, w2, lt     // min(width, height)
    lsr     w10, w10, #2        // base = min/4
    lsr     w12, w10, #2        // amp  = base/4
    mul     w9, w9, w12
    asr     w9, w9, #8          // osc = tri*amp/256  (-amp..+amp)

    add     w11, w10, w9        // R = base + osc
    lsl     w15, w11, #5        // R32 = R in 1/32px units
    sub     w14, w10, w9        // S = base - osc

    lsl     w16, w3, #7         // phase: 128 palette steps/frame
                                // (32768 steps = one full rainbow,
                                //  bands drift ~12px/sec)

    adrp    x17, rainbow@PAGE
    add     x17, x17, rainbow@PAGEOFF

    lsr     w5, w1, #1          // cx
    lsr     w6, w2, #1          // cy

    mov     w3, #0
Ly_loop:
    cmp     w3, w2
    b.ge    Ldone
    mov     w4, #0
Lx_loop:
    cmp     w4, w1
    b.ge    Lnext_row

    sub     w7, w4, w5          // dx
    sub     w8, w3, w6          // dy
    cmp     w7, #0
    cneg    w9, w7, lt          // |dx|
    cmp     w8, #0
    cneg    w10, w8, lt         // |dy|

    // ---- dc32 = |32*sqrt(d2) - R32|  (1/32px units) ----
    mul     w12, w7, w7
    madd    w12, w8, w8, w12    // d2
    lsl     w12, w12, #10       // d2 * 1024  (see note above)
    scvtf   s0, w12
    fsqrt   s0, s0
    fcvtzs  w12, s0             // r32 = 32 * radial distance
    sub     w12, w12, w15       // r32 - R32
    cmp     w12, #0
    cneg    w12, w12, lt        // dc32

    // ---- ds = |max(|dx|,|dy|) - S|  (integer px, for line test) ----
    cmp     w9, w10
    csel    w13, w9, w10, gt
    sub     w13, w13, w14
    cmp     w13, #0
    cneg    w13, w13, lt        // ds

    // ---- d32 = min(dc32, ds*32): distance to nearest line ----
    lsl     w10, w13, #5        // ds32
    cmp     w12, w10
    csel    w9, w12, w10, lt    // d32

    // ---- default darkness ----
    movz    w11, #0x1018
    movk    w11, #0xFF10, lsl #16

    // ---- rainbow halo: within 64px (2048 in 1/32px) ----
    cmp     w9, #2048
    b.ge    Lline_check
    add     w10, w9, w9, lsl #2 // d32 * 5
    lsl     w10, w10, #2        // d32 * 20 -> full rainbow / ~51px
    add     w10, w10, w16       // + phase
    and     w10, w10, #0x7FFF   // wrap to 32768 entries
    ldr     w11, [x17, w10, uxtw #2]

Lline_check:
    // ---- square line: ds <= 1  (3px) ----
    cmp     w13, #1
    b.gt    Lcircle_line
    movz    w11, #0xFF66
    movk    w11, #0xFF00, lsl #16
Lcircle_line:
    // ---- circle line: dc32 <= 64  (2px in 1/32px units) ----
    cmp     w12, #64
    b.gt    Lput_pixel
    movz    w11, #0x00FF
    movk    w11, #0xFFFF, lsl #16

Lput_pixel:
    madd    w13, w3, w1, w4
    str     w11, [x0, w13, uxtw #2]
    add     w4, w4, #1
    b       Lx_loop

Lnext_row:
    add     w3, w3, #1
    b       Ly_loop
Ldone:
    ret

